import csv
from datetime import datetime

ts_map = {
 'F2_Z01_t': 'baef86cb-2941-5d61-87b0-ffa91d79f23a',
 'F2_Z01_sp': '1213f3a8-c23d-55b5-8187-4712d49a82ae',
 'F3_Z01_t': 'e0dd5f44-f050-5faa-a2a0-a3fcb6284ae8',
 'F3_Z01_sp': '5b98cbc1-fd25-5d8c-a96e-c3de49819174',
 'F4_Z01_t': '14a08406-79a0-52ca-b8a1-8563259dc820',
 'F4_Z01_sp': '22de734e-0a64-57ec-a6a5-f288ee06f947',
}
keys = ts_map
data = {tid: {} for tid in keys.values()}
with open(VALUES_CSV) as f:
    rdr = csv.reader(f); next(rdr)
    for ts, t, v in rdr:
        if ts in data:
            data[ts][t] = float(v)

def occupied(h):
    dt = datetime.fromisoformat(h)
    return dt.weekday() < 5 and 9 <= dt.hour <= 16

def agg(tid, month_prefix):
    tvs = [data[tid][t] for t in data[tid] if t.startswith(month_prefix) and occupied(t)]
    if not tvs: return None
    return sum(tvs)/len(tvs), len(tvs)

for label, tid in ts_map.items():
    for mp in ['2018-04','2018-05','2018-06','2018-07']:
        r = agg(tid, mp)
        print(label, mp, r)
    print()
